@RestController
@RequestMapping("/api/v1/secure")
@Validated
public class SecureDataController {

    @PostMapping
    public ResponseEntity<String> processSecureData(
            @RequestHeader("X-Signature") String clientSignature,
            @RequestHeader("X-Timestamp") long timestamp,
            @Valid @RequestBody SecurePayload payload) {

        // Guard against replay attacks (e.g., 5-minute window tolerance)
        if (Math.abs(System.currentTimeMillis() - timestamp) > 300000) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Request expired");
        }

        return ResponseEntity.ok("Processed successfully");
    }
}
